package io.knowledgebrain.collaboration;
import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import javax.sql.DataSource;import jakarta.servlet.http.HttpServletRequest;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;
@RestController @ConditionalOnProperty(name="brain.collaboration.review-export.enabled",havingValue="true")
final class ReviewSignalExportController {
 record Page(List<ReviewSignal.Signal> items,UUID nextAfter) {}
 private final JdbcTemplate sql;private final byte[] key;
 ReviewSignalExportController(DataSource ds,@Value("${brain.collaboration.review-export.key}")String key){if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Dedicated credential required");sql=new JdbcTemplate(ds);this.key=("Bearer "+key).getBytes(StandardCharsets.US_ASCII);}
 Page page(UUID after,int limit){if(limit<1||limit>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);var rows=sql.query("SELECT aggregatetype,payload,id FROM outbox_event WHERE aggregatetype IN ('submission-feedback','resubmission-request','submission-grade','feedback-retraction','grade-retraction') AND id>? ORDER BY id LIMIT ?",(rs,n)->{var s=ReviewSignal.decode("collaboration."+rs.getString(1)+".v1",rs.getBytes(2));if(!s.eventId().equals(rs.getObject(3,UUID.class)))throw ReviewSignal.bad();return s;},after==null?new UUID(0,0):after,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(items,rows.size()>limit?items.getLast().eventId():null);}
 @GetMapping("/internal/collaboration/review-signals") ResponseEntity<Page> export(HttpServletRequest r){var h=Collections.list(r.getHeaders("Authorization"));if(!r.isSecure()||h.size()!=1||!MessageDigest.isEqual(key,h.getFirst().getBytes(StandardCharsets.US_ASCII)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);if(r.getHeader("Cookie")!=null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);for(var v:r.getParameterMap().entrySet())if(!Set.of("after","limit").contains(v.getKey())||v.getValue().length!=1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);try{String limit=r.getParameter("limit");if(limit!=null&&!limit.matches("[1-9][0-9]{0,2}"))throw ReviewSignal.bad();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(page(r.getParameter("after")==null?null:ReviewSignal.id(r.getParameter("after")),limit==null?50:Integer.parseInt(limit)));}catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST);}}
}
